        dummy.rotation.set(0, e.yaw, 0);
        dummy.scale.set(e.sx, e.sy, e.sx);
        dummy.updateMatrix();
        mesh.setMatrixAt(i, dummy.matrix);
        phases[i] = e.phase;
        shades[i] = e.shade;
