    const label =
      phase < 0.05 ? '黎明' :
      phase < 0.22 ? '清晨' :
      phase < 0.34 ? '正午' :
      phase < 0.47 ? '午后' :
      phase < 0.56 ? '黄昏' :
      phase < 0.72 ? '入夜' : '深夜';

