      const low = 1 - smooth01(0.08, 0.58, sunAlt);
      const ember = Math.pow(1 - smooth01(-0.01, 0.16, sunAlt), 1.3);
      scratch.key
        .copy(PALETTE.keyDay)
        .lerp(PALETTE.keyGolden, low)
        .lerp(PALETTE.keyEmber, ember * 0.6);
